.payment-field-help{font-size:.82rem;line-height:1.45;color:#64748b;font-weight:400}transaction-form-card-clean{display:grid;gap:26px;min-width:0}.transaction-section{min-width:0}.transaction-form-card-clean .transaction-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.transaction-form-card-clean .transaction-field{display:flex;flex-direction:column;gap:7px;min-width:0}.transaction-form-card-clean input,.transaction-form-card-clean select{width:100%;min-width:0;box-sizing:border-box}.transaction-address-field{grid-column:1/-1}.transaction-form-section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.transaction-form-section-head h2{margin:0}.transaction-form-section-head p{margin:4px 0 0;color:#64748b}.transaction-entry-panel{padding:18px;border:1px solid #bfdbfe;border-radius:12px;background:#f8fbff;margin-bottom:14px}.transaction-entry-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:14px}.transaction-item-type-row{display:flex;align-items:center;gap:8px;margin-bottom:18px}.transaction-type-choice{border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#334155;padding:10px 18px;font-weight:600;cursor:pointer}.transaction-type-choice.is-active{background:#1d4ed8;border-color:#1d4ed8;color:#fff}.transaction-type-choice:focus-visible{outline:3px solid #93c5fd;outline-offset:2px}.transaction-added-list{display:grid;gap:10px}.transaction-added-row{display:grid;grid-template-columns:100px minmax(150px,2fr) minmax(65px,.6fr) minmax(130px,1fr) auto;align-items:center;gap:14px;padding:14px 16px;border:1px solid #e2e8f0;border-radius:10px;background:#fff}.transaction-added-row input[type=hidden]{display:none}.added-kind{font-size:.8rem;color:#64748b}.added-title{font-weight:600;color:#173b70}.added-price{color:#64748b}.transaction-remove-line{border:1px solid #fecaca;color:#dc2626;background:#fff;padding:8px 12px;border-radius:8px}.transaction-remove-line[hidden]{display:none}.transaction-totals-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:18px}.transaction-totals-grid>div{display:flex;flex-direction:column;gap:8px;padding:16px;border:1px solid #e2e8f0;border-radius:10px;background:#f8fafc}.transaction-totals-grid span{color:#64748b;font-size:.88rem}.transaction-totals-grid strong{font-size:1.2rem;color:#173b70}@media(max-width:900px){.transaction-entry-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.transaction-added-row{grid-template-columns:repeat(2,minmax(0,1fr))}.transaction-totals-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.transaction-form-card-clean .transaction-form-grid,.transaction-entry-grid,.transaction-added-row{grid-template-columns:minmax(0,1fr)}.transaction-form-section-head{align-items:flex-start;flex-direction:column}}
</style>
<script>
(function(){
 const catalog=@json($serviceCatalog),prices=@json($priceCatalog),products=@json($products);let nextIndex={{ count($details) }};const rows=document.getElementById('transactionItemRows');
 const money=n=>'₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
 const serviceFields=document.getElementById('serviceFields'),productFields=document.getElementById('productFields'),chooseService=document.getElementById('chooseService'),chooseProduct=document.getElementById('chooseProduct');let selectedKind='service';
 function chooseKind(kind){selectedKind=kind;serviceFields.hidden=kind!=='service';productFields.hidden=kind!=='product';chooseService.classList.toggle('is-active',kind==='service');chooseProduct.classList.toggle('is-active',kind==='product');}
 chooseService.addEventListener('click',()=>chooseKind('service'));chooseProduct.addEventListener('click',()=>chooseKind('product'));
 const serviceType=document.getElementById('newServiceType'),serviceSize=document.getElementById('newServiceSize'),servicePrice=document.getElementById('newServicePrice');
 function updateServiceSizes(){serviceSize.innerHTML='<option value="">Choose size</option>';Object.entries(catalog[serviceType.value]?.sizes||{}).forEach(([size])=>serviceSize.add(new Option(size,size)));serviceSize.disabled=!serviceType.value;updateServicePrice();}
 function updateServicePrice(){const p=prices[serviceType.value]?.[serviceSize.value];servicePrice.value=p===null||p===undefined?'':Number(p).toFixed(2);}
 serviceType.addEventListener('change',updateServiceSizes);serviceSize.addEventListener('change',updateServicePrice);
 const productSelect=document.getElementById('newProduct');
 function productQuantityInRows(productId){let total=0;rows.querySelectorAll('.transaction-added-row[data-kind="product"]').forEach(row=>{const id=row.querySelector('input[name$="[inventory_item_id]"]')?.value;if(String(id)===String(productId))total+=Number(row.querySelector('input[name$="[quantity]"]')?.value||0);});return total;}
 function updateProductAvailability(){const o=productSelect.selectedOptions[0],stockField=document.getElementById('newProductStock'),qtyField=document.getElementById('newProductQuantity');if(!o||!o.value){document.getElementById('newProductPrice').value='Select product';stockField.value='Choose product';qtyField.max=100000;return;}const remaining=Math.max(0,Number(o.dataset.stock)-productQuantityInRows(o.value));document.getElementById('newProductPrice').value=money(o.dataset.price);stockField.value=remaining+' available to add';qtyField.max=remaining;if(Number(qtyField.value)>remaining)qtyField.value=remaining>0?remaining:'';}
 productSelect.addEventListener('change',updateProductAvailability);
 document.getElementById('newProductQuantity').addEventListener('input',()=>{const o=productSelect.selectedOptions[0];if(o&&o.value){const remaining=Math.max(0,Number(o.dataset.stock)-productQuantityInRows(o.value));if(Number(document.getElementById('newProductQuantity').value)>remaining)document.getElementById('newProductQuantity').value=remaining>0?remaining:'';}});
 function createRow(kind,values){if(rows.children.length>=30){alert('A transaction can contain up to 30 items.');return;}const idx=nextIndex++,row=document.createElement('div');row.className='transaction-added-row';row.dataset.kind=kind;let title='',price=0,fields='';
 if(kind==='service'){title=values.service+' · '+values.size;price=Number(values.price);fields=`<input type="hidden" name="details[${idx}][line_type]" value="service"><input type="hidden" name="details[${idx}][service_type]" value="${values.service}"><input type="hidden" name="details[${idx}][service_size]" value="${values.size}"><input type="hidden" name="details[${idx}][unit_price]" value="${price}">`;}
 else{const p=products.find(x=>String(x.id)===String(values.product));title=p?p.name:'Product';price=p?p.price:0;fields=`<input type="hidden" name="details[${idx}][line_type]" value="product"><input type="hidden" name="details[${idx}][inventory_item_id]" value="${values.product}">`;}
 if(kind==='product')fields+=`<input type="hidden" name="details[${idx}][unit_price]" value="${price}">`;fields+=`<input type="hidden" name="details[${idx}][quantity]" value="${values.quantity}">`;row.innerHTML=fields+`<span class="added-kind">${kind==='product'?'Merchandise':'Service'}</span><span class="added-title"></span><span>Qty: ${values.quantity}</span><span class="added-price">${price===null||price===undefined?'Not configured':money(Number(price)*Number(values.quantity))}</span><button type="button" class="transaction-remove-line">Remove</button>`;row.querySelector('.added-title').textContent=title;rows.appendChild(row);refreshRemoveButtons();updateTotals();}
 document.getElementById('addTransactionItem').addEventListener('click',()=>{if(selectedKind==='service'){if(!serviceType.value||!serviceSize.value){alert('Choose a service and size first.');return;}const price=Number(servicePrice.value);if(servicePrice.value.trim()===''||!Number.isFinite(price)||price<0){alert('Enter a valid service price.');return;}const qty=Number(document.getElementById('newServiceQuantity').value);if(!Number.isInteger(qty)||qty<1||qty>100000){alert('Enter a valid quantity.');return;}createRow('service',{service:serviceType.value,size:serviceSize.value,quantity:qty,price});serviceType.value='';serviceSize.innerHTML='<option value="">Choose service first</option>';serviceSize.disabled=true;document.getElementById('newServiceQuantity').value=1;servicePrice.value='';}else{if(!productSelect.value){alert('Choose a product first.');return;}const opt=productSelect.selectedOptions[0],qty=Number(document.getElementById('newProductQuantity').value);if(!Number.isInteger(qty)||qty<1||qty>100000){alert('Enter a valid quantity.');return;}const remaining=Math.max(0,Number(opt.dataset.stock)-productQuantityInRows(productSelect.value));if(qty>remaining){alert('Only '+remaining+' more unit(s) of this product can be added.');updateProductAvailability();return;}createRow('product',{product:productSelect.value,quantity:qty});productSelect.value='';document.getElementById('newProductPrice').value='Select product';document.getElementById('newProductStock').value='Choose product';document.getElementById('newProductQuantity').value=1;}});
 function refreshRemoveButtons(){rows.querySelectorAll('.transaction-remove-line').forEach(b=>{b.hidden=false;});if(productSelect.value)updateProductAvailability();}
 document.addEventListener('click',e=>{if(e.target.matches('.transaction-remove-line')){e.target.closest('.transaction-added-row').remove();refreshRemoveButtons();updateTotals();}});
 function updateTotals(){let subtotal=0;rows.querySelectorAll('.transaction-added-row').forEach(r=>{const q=Number(r.querySelector('input[name$="[quantity]"]')?.value||0);if(r.dataset.kind==='service'){const p=Number(r.querySelector('input[name$="[unit_price]"]')?.value);if(Number.isFinite(p))subtotal+=p*q;}else{const id=r.querySelector('input[name$="[inventory_item_id]"]')?.value,p=products.find(x=>String(x.id)===String(id))?.price;if(p!==undefined)subtotal+=Number(p)*q;}});const typ=document.getElementById('discountType').value,val=Math.max(0,Number(document.getElementById('discountValue').value||0)),disc=Math.min(subtotal,typ==='percentage'?subtotal*Math.min(val,100)/100:val),total=subtotal-disc;document.getElementById('transactionSubtotal').textContent=money(subtotal);document.getElementById('transactionDiscount').textContent=money(disc);document.getElementById('transactionTotal').textContent=money(total);document.getElementById('discountValue').disabled=!typ;document.getElementById('discountValueHelp').textContent=typ==='fixed'?'Enter the discount amount in pesos.':typ==='percentage'?'Enter the discount percentage, from 0 to 100.':'Choose a discount type first. Enter the amount in pesos or the percentage, depending on the type.';}
 ['discountType','discountValue'].forEach(id=>document.getElementById(id).addEventListener('input',updateTotals));refreshRemoveButtons();updateTotals();
 document.querySelector('form').addEventListener('submit',e=>{if(!rows.querySelector('.transaction-added-row')){e.preventDefault();alert('Add at least one service or product.');}});
})();
</script>
